use std::io

fn find(names: Vec<string>, name: string) -> int {
    let mut i = 0
    while i < names.len() {
        if names[i] == name {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = io::read_to_string() ?? ""
    let mut names: Vec<string> = Vec::new()
    let mut bals: Vec<int> = Vec::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" {
            let amt: int = p[2].parse() ?? 0
            if amt < 0 {
                println("error: invalid amount")
            } else if find(names, p[1]) >= 0 {
                println("error: duplicate account")
            } else {
                names.push(p[1])
                bals.push(amt)
                println("ok")
            }
        } else if cmd == "balance" {
            let i = find(names, p[1])
            if i < 0 {
                println("error: unknown account ${p[1]}")
            } else {
                println("${bals[i]}")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt: int = p[2].parse() ?? 0
            let i = find(names, p[1])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${p[1]}")
            } else if cmd == "deposit" {
                bals[i] = bals[i] + amt
                println("ok")
            } else if bals[i] < amt {
                println("error: insufficient funds")
            } else {
                bals[i] = bals[i] - amt
                println("ok")
            }
        } else if cmd == "transfer" {
            let amt: int = p[3].parse() ?? 0
            let a = find(names, p[1])
            let b = find(names, p[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if a < 0 {
                println("error: unknown account ${p[1]}")
            } else if b < 0 {
                println("error: unknown account ${p[2]}")
            } else if a == b {
                println("error: same account")
            } else if bals[a] < amt {
                println("error: insufficient funds")
            } else {
                bals[a] = bals[a] - amt
                bals[b] = bals[b] + amt
                println("ok")
            }
        }
    }
    let n = names.len()
    let mut i = 1
    while i < n {
        let mut j = i
        while j > 0 && names[j - 1] > names[j] {
            let tn = names[j - 1]
            names[j - 1] = names[j]
            names[j] = tn
            let tb = bals[j - 1]
            bals[j - 1] = bals[j]
            bals[j] = tb
            j -= 1
        }
        i += 1
    }
    let mut k = 0
    while k < n {
        println("${names[k]} ${bals[k]}")
        k += 1
    }
}

